/*! tailwindcss v4.3.3 | MIT License | https://tailwindcss.com */
:root, :host {
  --spacing: 0.25rem;
  --container-xl: 36rem;
}
.ms-auto {
  margin-inline-start: auto;
}
.-mt-\[8px\] {
  margin-top: calc(8px * -1);
}
.flex {
  display: flex;
}
.grid {
  display: grid;
}
.size-\[80px\] {
  width: 80px;
  height: 80px;
}
.w-1\/2 {
  width: calc(1 / 2 * 100%);
}
.w-\[320px\] {
  width: 320px;
}
.max-w-xl {
  max-width: var(--container-xl);
}
.grid-cols-3 {
  grid-template-columns: repeat(3, minmax(0, 1fr));
}
.grid-rows-2 {
  grid-template-rows: repeat(2, minmax(0, 1fr));
}
.flex-col {
  flex-direction: column;
}
.items-center {
  align-items: center;
}
.justify-between {
  justify-content: space-between;
}
.gap-\[12px\] {
  gap: 12px;
}
.gap-x-6 {
  column-gap: calc(var(--spacing) * 6);
}
.gap-y-4 {
  row-gap: calc(var(--spacing) * 4);
}
.rounded-\[12px\] {
  border-radius: 12px;
}
.bg-\[\#112233\]\/50 {
  background-color: color-mix(in oklab, #112233 50%, transparent);
}
.p-6 {
  padding: calc(var(--spacing) * 6);
}
.px-8 {
  padding-inline: calc(var(--spacing) * 8);
}
.py-4 {
  padding-block: calc(var(--spacing) * 4);
}
.pt-\[12px\] {
  padding-top: 12px;
}
